            {
                public bool ActiveProposal { get; set; }

                public bool KycStatus { get; set; }

                public ulong KycExpiring { get; set; }

                public byte[] ToByteArray()
                {
                    var ret = new List<byte>();
                    var stringRef = new Dictionary<int, byte[]>();
                    AVM.ClientGenerator.ABI.ARC4.Types.WireType vActiveProposal = AVM.ClientGenerator.ABI.ARC4.Types.WireType.FromABIDescription("bool");
                    vActiveProposal.From(ActiveProposal);
                    ret.AddRange(vActiveProposal.Encode());
                    AVM.ClientGenerator.ABI.ARC4.Types.WireType vKycStatus = AVM.ClientGenerator.ABI.ARC4.Types.WireType.FromABIDescription("bool");
                    vKycStatus.From(KycStatus);
                    ret.AddRange(vKycStatus.Encode());
                    AVM.ClientGenerator.ABI.ARC4.Types.WireType vKycExpiring = AVM.ClientGenerator.ABI.ARC4.Types.WireType.FromABIDescription("uint64");
                    vKycExpiring.From(KycExpiring);
                    ret.AddRange(vKycExpiring.Encode());
                    foreach (var item in stringRef)
                    {
                        var b1 = ret.Count;
                        ret[item.Key] = Convert.ToByte(b1 / 256);
                        ret[item.Key + 1] = Convert.ToByte(b1 % 256);
                        ret.AddRange(item.Value);
                    }
                    return ret.ToArray();

                }

